<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {Bell,RefreshCw,CheckCheck,ArrowUpRight} from 'lucide-vue-next'
import {useAuthStore,type Notification} from '@/stores/auth'
import {canVisit} from '@/utils/permissions'
const auth=useAuthStore(),router=useRouter(),filter=ref('all'),kind=ref('all'),limit=ref(20),busy=ref(false),error=ref('')
const filtered=computed(()=>auth.notifications.filter(n=>(filter.value!=='unread'||!n.isRead)&&(kind.value==='all'||n.type===kind.value)))
watch([filter,kind],()=>{limit.value=20})
onMounted(()=>auth.loadNotifications())
async function read(n:Notification){busy.value=true;error.value='';try{await auth.markNotificationAsRead(n.id)}catch(e:any){error.value=e.message||'已读状态保存失败'}finally{busy.value=false}}
async function allRead(){busy.value=true;error.value='';try{await auth.markAllAsRead()}catch(e:any){error.value=e.message||'部分通知未能标记，请重试'}finally{busy.value=false}}
function canOpen(n:Notification){const path=n.targetPath?.split('?')[0];return !!path&&canVisit(Number(auth.effectiveRoleId),path)&&auth.hasMenu(path)}
async function open(n:Notification){await read(n);if(!error.value&&n.targetPath)router.push(n.targetPath)}
const source=(n:Notification)=>n.source==='business'?'业务动态':n.source==='security'?'账号安全':'通知公告'
</script>
<template><section class="notification-inbox" aria-label="我的通知">
 <header><div><p class="inbox-eyebrow">MOUSE MES · 消息中心</p><h1>我的通知 <span>{{auth.unreadCount}} 条未读</span></h1><p>{{Number(auth.effectiveRoleId)===9?'汇总库存预警、设备维修与生产进度，点击即可进入关联业务。':'查看面向本人的通知公告与账号安全提醒。'}}</p></div><div class="inbox-actions"><button :disabled="auth.notificationLoading" @click="auth.loadNotifications()"><RefreshCw :size="15"/>刷新</button><button :disabled="busy||!auth.unreadCount" @click="allRead"><CheckCheck :size="15"/>全部已读</button></div></header>
 <nav aria-label="通知筛选"><button :class="{active:filter==='all'}" @click="filter='all'">全部通知 {{auth.notifications.length}}</button><button :class="{active:filter==='unread'}" @click="filter='unread'">只看未读 {{auth.unreadCount}}</button><select v-model="kind" aria-label="通知类型"><option value="all">全部类型</option><option value="info">信息</option><option value="warning">提醒</option><option value="success">进展</option><option value="danger">异常</option></select></nav>
 <p v-if="error||auth.notificationError" role="alert" class="inbox-error">{{error||auth.notificationError}}</p>
 <p v-if="auth.notificationLoading&&!auth.notifications.length" class="inbox-empty">正在读取通知…</p>
 <div v-else><article v-for="n in filtered.slice(0,limit)" :key="n.id" :class="{unread:!n.isRead}"><div class="notice-icon" :class="n.type"><Bell :size="19"/></div><div class="notice-body"><div class="notice-heading"><h2>{{n.title}}</h2><span class="read-state">{{n.isRead?'已读':'未读'}}</span></div><p>{{n.content}}</p><footer><span>{{source(n)}} · {{String(n.createdAt).replace('T',' ').slice(0,19)}}</span><div><button v-if="!n.isRead" :disabled="busy" @click="read(n)">标记已读</button><button v-if="canOpen(n)" :disabled="busy" @click="open(n)">查看业务<ArrowUpRight :size="14"/></button></div></footer></div></article>
 <div v-if="!filtered.length" class="inbox-empty"><Bell :size="30"/><p>{{filter==='unread'?'未读通知已处理完毕':'暂无符合条件的通知'}}</p></div><button v-if="filtered.length>limit" class="load-more" @click="limit+=20">加载更多（还有 {{filtered.length-limit}} 条）</button></div>
 <p class="inbox-note">业务消息记录生成时的状态，当前进度以关联业务页面为准。已读状态会保存，刷新后仍可查看。</p>
</section></template>
<style scoped>
.notification-inbox{background:#fff;border:1px solid #e4ddd2;border-radius:15px;overflow:hidden;color:#604c37;min-width:0}.notification-inbox>header{padding:26px;display:flex;justify-content:space-between;align-items:center;gap:20px;background:linear-gradient(110deg,#faf7f0,#f1e8da)}.inbox-eyebrow{font-size:11px;letter-spacing:2px;color:#a38460}.notification-inbox h1{font-size:25px;font-weight:650;margin:7px 0}.notification-inbox h1 span{font-size:12px;font-weight:500;margin-left:10px;padding:5px 10px;border-radius:16px;background:#e9dfcc;color:#8a643b}.notification-inbox>header p:last-child{font-size:13px;line-height:1.7;color:#95816b}.inbox-actions{display:flex;gap:8px;flex-shrink:0}.notification-inbox button{display:inline-flex;align-items:center;justify-content:center;gap:6px;font-size:12px;color:#8c6944}.inbox-actions button{padding:9px 12px;border:1px solid #dbcaaf;border-radius:8px;background:#fffdf8}.notification-inbox>nav{display:flex;gap:9px;flex-wrap:wrap;padding:16px 24px;border-bottom:1px solid #eae3d8}.notification-inbox>nav button{padding:8px 12px;border-radius:8px}.notification-inbox>nav button.active{background:#efe6d8;color:#795632;font-weight:600}.notification-inbox select{margin-left:auto;font-size:12px;padding:7px 10px;border:1px solid #e0d7c9;border-radius:8px;background:#fff}.notification-inbox article{display:flex;gap:14px;padding:23px 25px;border-bottom:1px solid #eee9e1}.notification-inbox article.unread{background:linear-gradient(90deg,#fbf8f1,#fff)}.notice-icon{width:38px;height:38px;display:grid;place-items:center;flex-shrink:0;border-radius:11px;background:#efe8dc;color:#9c7850}.notice-icon.warning{background:#f5ecd9;color:#a48046}.notice-icon.success{background:#e9efe5;color:#728366}.notice-icon.danger{background:#f6e9e4;color:#ad7664}.notice-body{min-width:0;flex:1}.notice-heading{display:flex;gap:12px;align-items:center;justify-content:space-between}.notice-heading h2{font-size:15px;font-weight:600;line-height:1.6}.read-state{font-size:11px;flex-shrink:0;color:#a69581}.unread .read-state{color:#a77c3b}.notice-body>p{font-size:13px;line-height:1.9;color:#897c6b;margin-top:7px;overflow-wrap:anywhere}.notice-body footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:13px;font-size:11px;color:#ac9d89}.notice-body footer>div{display:flex;gap:16px}.inbox-empty{padding:40px;display:flex;flex-direction:column;align-items:center;gap:12px;color:#a09483;font-size:13px}.inbox-error{padding:14px 25px;color:#af6d5b;font-size:13px}.inbox-note{padding:16px 24px;color:#ac9b84;font-size:11px;background:#fcfaf6;line-height:1.8}.load-more{width:100%;padding:16px;background:#faf7f1}.notification-inbox button:disabled{opacity:.5;cursor:default}.notification-inbox button:focus-visible{outline:2px solid #b99c73;outline-offset:3px}@media(max-width:700px){.notification-inbox>header{align-items:flex-start;flex-direction:column;padding:20px}.notification-inbox article{padding:18px}.notification-inbox>nav{padding:12px}.notification-inbox h1{font-size:22px}}
</style>
